      Testo.create
        "scattered hits cannot replace an anchor with a short fragment"
        (fun () ->
          with_db (fun db ->
              let query = unique_text 256 in
              let target =
                String.concat (String.make 1600 'z')
                  (List.init 4 (fun i -> String.sub query (i * 64) 64))
              in
              let original = anchor db query in
              ignore (put db "destination.ml" target);
              ignore (put db "original.ml" "removed");
              Testo.check Testo.bool true (Text.search db query = []);
              let a = current db original in
              Testo.check Testo.bool true (a.status = Text.Outdated);
              Testo.check Testo.string query a.raw_contents;
              Testo.check Testo.bool true (a.range = original.range);
              Testo.check Testo.string "original.ml" a.source_doc.locator));
      Testo.create
        "a returned range must reach half the normalized anchor length \
         rounded up" (fun () ->
          List.iter
            (fun (query_length, match_length, accepted) ->
              with_db (fun db ->
                  let text = unique_text (query_length - 1) in
                  let query =
                    String.sub text 0 47 ^ " "
                    ^ String.sub text 47 (query_length - 48)
                  in
                  let fragment =
                    String.sub query 0 47 ^ String.make 100 ' '
                    ^ String.sub query 48 (match_length - 48)
                  in
                  (* Additional distant hits pass the initial document filter but
               cannot extend the local alignment around the modal offset. *)
                  let target =
                    fragment ^ String.make 1600 'z' ^ String.sub query 200 32
                  in
                  let original = anchor db query in
                  ignore (put db "destination.ml" target);
                  ignore (put db "original.ml" "removed");
                  let results = Text.search db query in
                  Testo.check Testo.int
                    (if accepted then 1 else 0)
                    (List.length results);
                  let a = current db original in
                  if accepted then begin
                    Testo.check Testo.string "destination.ml"
                      a.source_doc.locator;
                    Testo.check Testo.string fragment a.raw_contents
                  end
                  else begin
                    Testo.check Testo.bool true (a.status = Text.Outdated);
                    Testo.check Testo.string query a.raw_contents
                  end))
            [
              (256, 127, false);
              (256, 128, true);
              (257, 128, false);
              (257, 129, true);
            ]);
      Testo.create
        "whitespace cannot inflate a weak scattered fragment into a match"
        (fun () ->
          with_db (fun db ->
              let text = unique_text 255 in
              let query =
                String.sub text 0 47 ^ " " ^ String.sub text 47 208
              in
              let inflated =
                String.sub query 0 47 ^ String.make 100 ' '
                ^ String.sub query 48 48
              in
              let scattered =
                List.init 5 (fun i ->
                    String.make 1600 'z' ^ String.sub query (96 + (i * 32)) 32)
              in
              let target = inflated ^ String.concat "" scattered in
              let original = anchor db query in
              ignore (put db "destination.ml" target);
              ignore (put db "original.ml" "removed");
              Testo.check Testo.bool true (Text.search db query = []);
              let a = current db original in
              Testo.check Testo.bool true (a.status = Text.Outdated);
              Testo.check Testo.string query a.raw_contents;
              Testo.check Testo.bool true (a.range = original.range)));
      Testo.create "unrelated interior bytes cannot inflate alignment support"
        (fun () ->
          with_db (fun db ->
              let query = unique_text 256 in
              (* Two nearby blocks align across unrelated text. A distant block
                 supplies the remaining shingles for the document filter. Only
                 120 bytes support the selected local alignment. *)
              let target =
                String.sub query 0 64 ^ String.make 80 'z'
                ^ String.sub query 72 56 ^ String.make 1600 'z'
                ^ String.sub query 200 32
              in
              let aligned =
                Option.get
                  (Util.Smith_waterman.align Util.Smith_waterman.code query
                     target)
              in
              Testo.check Testo.bool true
                (aligned.target.end_ - aligned.target.start >= 128);
              Testo.check Testo.int 120 aligned.identical_bytes;
              let original = anchor db query in
              ignore (put db "destination.ml" target);
              ignore (put db "original.ml" "removed");
              Testo.check Testo.bool true (Text.search db query = []);
              Testo.check Testo.bool true
                ((current db original).status = Text.Outdated)));
      Testo.create
        "alignment endpoints are narrowed to whole UTF-8 characters"
        (fun () ->
          with_db (fun db ->
              let middle = unique_text 160 in
              let query = "ũ" ^ middle ^ "ê" in
              let target = "ĩ" ^ middle ^ "é" in
              relocate db query target (fun a ->
                  Testo.check Testo.string middle a.raw_contents;
                  Testo.check Testo.int 2 a.range.start;
                  Testo.check Testo.int 162 a.range.end_)));
      Testo.create "trimmed partial characters do not count toward support"
        (fun () ->
          with_db (fun db ->
              let text = unique_text 320 in
              let middle = String.sub text 80 160 in
              let query =
                String.sub text 0 80 ^ "ũ" ^ middle ^ "ê"
                ^ String.sub text 240 80
              in
              let target =
                "ĩ" ^ middle ^ "é" ^ String.make 1600 'z'
                ^ String.sub text 0 32
              in
              let original = anchor db query in
              ignore (put db "destination.ml" target);
              ignore (put db "original.ml" "removed");
              Testo.check Testo.bool true (Text.search db query = []);
              Testo.check Testo.bool true
                ((current db original).status = Text.Outdated)));
      Testo.create "whitespace contraction does not disqualify a full match"
        (fun () ->
          with_db (fun db ->
              let text = unique_text 160 in
              let query =
                String.sub text 0 80 ^ String.make 300 ' '
                ^ String.sub text 80 80
              in
              let target =
                String.sub text 0 80 ^ " " ^ String.sub text 80 80
              in
              relocate db query target (fun a ->
                  Testo.check Testo.string target a.raw_contents;
                  Testo.check Testo.int 0 a.range.start;
                  Testo.check Testo.int (String.length target) a.range.end_)));
    ]
